const { withGradleProperties } = require("expo/config-plugins");

const GRADLE_JVM_ARGS = "-Xmx4g -XX:MaxMetaspaceSize=1g";

/**
 * Keeps Gradle's daemon memory settings in the generated Android project.
 * The Android directory is regenerated by Expo prebuild and is not committed.
 */
module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (modConfig) => {
    const property = modConfig.modResults.find(
      (item) => item.type === "property" && item.key === "org.gradle.jvmargs",
    );

    if (property) {
      property.value = GRADLE_JVM_ARGS;
    } else {
      modConfig.modResults.push({
        type: "property",
        key: "org.gradle.jvmargs",
        value: GRADLE_JVM_ARGS,
      });
    }

    return modConfig;
  });
};
